entries[26785] = { ["name"] = "Beruhigendes Gift", ["text"] = "Wirken in 3 sek.\nBenötigt Nahkampfwaffe\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt. Bei jedem Schlag besteht eine Chance von 20%, den Gegner zu vergiften und sofort 134 bis 172 Naturschaden zuzufügen, ohne zusätzliche Bedrohung zu verursachen.\n(Procchance: 20%)" }
