entries[26839] = { ["name"] = "Erdrosseln", ["text"] = "50 Energie Nahkampfreichweite\nSofort\nBenötigt Verstohlenheit\nErdrosselt den Feind, bringt ihn für 3 Sek. zum Schweigen und verursacht 18 Sek. lang 666 Schaden, erhöht durch Angriffskraft. Muss verstohlen und hinter dem Ziel sein. Gewährt 1 Combopunkt." }
