entries[26863] = { ["name"] = "Meucheln", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nDas Ziel meucheln und ihm 150% Waffenschaden plus 255 zufügen. Muss hinter dem Ziel sein. In der Waffenhand muss sich ein Dolch befinden. Gewährt 1 Combopunkt." }
entries[26864] = { ["name"] = "Blutsturz", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin sofortiger Stoß, der 110% Waffenschaden sowie einen Blutsturz beim Ziel verursacht und so den dem Ziel zugefügten körperlichen Schaden um bis zu 42 erhöht. Hält 10 Aufladungen oder 15 Sek. lang an. Gewährt 1 Combopunkt." }
entries[26865] = { ["name"] = "Ausweiden", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der Schaden pro Combopunkt verursacht:\n1 Punkt: (60 + 185 + Angriffskraft * 0.03)-(180 + 185 + Angriffskraft * 0.03) Schaden\n2 Punkte: [60 + (370) + Angriffskraft * 0.06]-[180 + (370) + Angriffskraft * 0.06] Schaden\n3 Punkte: [60 + (555) + Angriffskraft * 0.09]-[180 + (555) + Angriffskraft * 0.09] Schaden\n4 Punkte: [60 + (740) + Angriffskraft * 0.12]-[180 + (740) + Angriffskraft * 0.12] Schaden\n5 Punkte: [60 + (925) + Angriffskraft * 0.15]-[180 + (925) + Angriffskraft * 0.15] Schaden" }
entries[26866] = { ["name"] = "Rüstung schwächen", ["text"] = "25 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der eine Schwachstelle in der Rüstung des Ziels ausfindig macht und 30 Sek. lang Rüstung pro Combopunkt verringert:\n1 Punkt: 410 Rüstung\n2 Punkte: 820 Rüstung\n3 Punkte: 1230 Rüstung\n4 Punkte: 1640 Rüstung\n5 Punkte: 2050 Rüstung" }
