entries[26906] = { ["name"] = "Smaragdkrone der Zerstörung", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nGewaltiger Smaragd (2), Großer Opal (2), Blauer Saphir (2), Arkanitbarren (2), Thoriumbarren (2)\nSmaragdkrone der Zerstörung\nWird beim Anlegen gebunden\nKopf Stoff\n64 Rüstung\nHaltbarkeit 50 / 50\n50\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 30.\nAnlegen: Erhöht Eure kritische Zaubertrefferwertung um 14." }
entries[26907] = { ["name"] = "Ring des Ansturms", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nThoriumfassung , Mächtiges Mojo , Essenz der Erde\nRing des Ansturms\nWird beim Anlegen gebunden\nEinzigartig anlegbarFinger\n+5 Ausdauer\n51\nAnlegen: Erhöht die Angriffskraft um 24." }
entries[26908] = { ["name"] = "Saphiranhänger der Winternacht", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nBlauer Saphir , Essenz des Untodes , Thoriumfassung\nSaphiranhänger der Winternacht\nWird beim Anlegen gebunden\nHals\n51\nAnlegen: Erhöht durch Frostzauber und Frosteffekte zugefügten Schaden um bis zu 20.\nAnlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 20." }
entries[26909] = { ["name"] = "Figur - Smaragdeule", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nGewaltiger Smaragd (2), Arkanitbarren (2), Thoriumbarren (2), Mächtiges Mojo (4)\nFigur - Smaragdeule\nWird beim Aufheben gebunden\nEinzigartigSchmuck\n50\nBenötigt Juwelenschleifen\n(285)\nAnlegen: Stellt alle 5 Sek. 2 Mana wieder her.\nBenutzen: Stellt 12 Sek. lang pro Sekunde 60 Mana wieder her. (5 Min Abklingzeit)" }
entries[26910] = { ["name"] = "Ring der qualvollen Schatten", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nArkankristall , Essenz des Untodes (2), Dämonische Rune\nRing der qualvollen Schatten\nWird beim Anlegen gebunden\nEinzigartig anlegbarFinger\n52\nAnlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 20." }
entries[26911] = { ["name"] = "Lebendiger Smaragdanhänger", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nGewaltiger Smaragd (2), Essenz des Lebens (4), Mächtiges Mojo (4)\nLebendiger Smaragdanhänger\nWird beim Aufheben gebunden\nHals\n53\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 35 und den verursachten Schaden um bis zu 12.\nAnlegen: Stellt alle 5 Sek. 3 Mana wieder her." }
entries[26912] = { ["name"] = "Figur - Schwarzer Diamantkrebs", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nMakelloser schwarzer Diamant (4), Schwarzer Diamant (4), Azerothischer Diamant (2), Arkanitbarren (2), Thoriumbarren (4)\nFigur - Schwarzer Diamantkrebs\nWird beim Aufheben gebunden\nEinzigartigSchmuck\n55\nBenötigt Juwelenschleifen\n(300)\nAnlegen: Erhöht Verteidigungswertung um 9.\nBenutzen: Verringert 20 Sek. lang den erlittenen Nahkampfschaden um 35. (5 Min Abklingzeit)" }
entries[26914] = { ["name"] = "Figur - Dunkeleisenskorpid", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nDunkeleisenbarren (4), Arkanitbarren (2), Sternrubin (2)\nFigur - Dunkeleisenskorpid\nWird beim Aufheben gebunden\nEinzigartigSchmuck\n+9 Beweglichkeit\n55\nBenötigt Juwelenschleifen\n(300)\nBenutzen: Jeder Waffenschlag vergiftet Euren Gegner 20 Sek. lang und verursacht jede Sekunde 15 Schaden. (5 Min Abklingzeit)" }
entries[26915] = { ["name"] = "Halskette des Diamantturms", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nAzerothischer Diamant (2), Thoriumfassung (2), Arkanitbarren (2)\nHalskette des Diamantturms\nWird beim Anlegen gebunden\nHals\n+3 Arkanwiderstand\n+3 Feuerwiderstand\n+3 Naturwiderstand\n+3 Frostwiderstand\n+3 Schattenwiderstand\n56\nAnlegen: Erhöht Verteidigungswertung um 17." }
entries[26916] = { ["name"] = "Band des Naturfeuers", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nFlammenspessarit , Essenz des Feuers (4), Essenz des Lebens (4)\nBand des Naturfeuers\nWird beim Anlegen gebunden\nEinzigartig anlegbarFinger\n57\nAnlegen: Erhöht durch Naturzauber und Natureffekte zugefügten Schaden um bis zu 29.\nAnlegen: Erhöht durch Feuerzauber und Feuereffekte zugefügten Schaden um bis zu 29." }
entries[26918] = { ["name"] = "Arkanitschwertanhänger", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nArkanitbarren (4), Essenz der Erde (4), Essenz der Luft (4)\nArkanitschwertanhänger\nWird beim Anlegen gebunden\nHals\n58\nAnlegen: Erhöht die Angriffskraft um 40." }
entries[26920] = { ["name"] = "Blutkrone", ["text"] = "Wirken in 45 sek.\nTools: Juweliersset\nReagenzien:\nThoriumbarren (8), Blut des Berges (2), Sternrubin (4), Blut von Helden (2)\nBlutkrone\nWird beim Anlegen gebunden\nKopf Stoff\n75 Rüstung\nHaltbarkeit 50 / 50\n60\nAnlegen: Erhöht Eure kritische Trefferwertung um 28.\nAnlegen: Heilt Euch um 12 bis 18, wenn Ihr einen kritischen Treffer erzielt." }
