entries[26967] = { ["name"] = "Tödliches Gift VI", ["text"] = "Wirken in 3 sek.\nBenötigt Nahkampfwaffe\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 Sek. lang für 144 Naturschaden zu vergiften. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden.\n(Procchance: 30%)" }
