entries[26983] = { ["name"] = "Gelassenheit", ["text"] = "1650 ManaKanalisiert (Wirken in 8 sek.) 10 min Abklingzeit\nHeilt bei allen in der Nähe befindlichen Gruppenmitgliedern 8 Sek. lang alle 2 Sek. 1518 Gesundheit. Der Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten." }
