entries[26987] = { ["name"] = "Mondfeuer", ["text"] = "430 Mana 30 Meter Reichweite\nSofort\nVerbrennt den Feind und fügt ihm 238 bis 276 Arkanschaden sowie 12 Sek. lang 444 zusätzlichen Arkanschaden zu." }
entries[26988] = { ["name"] = "Mondfeuer", ["text"] = "495 Mana 30 Meter Reichweite\nSofort\nVerbrennt den Feind und fügt ihm 305 bis 357 Arkanschaden sowie 12 Sek. lang 600 zusätzlichen Arkanschaden zu." }
entries[26989] = { ["name"] = "Wucherwurzeln", ["text"] = "160 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nLässt das Ziel an Ort und Stelle festwurzeln und verursacht 27 Sek. lang insgesamt 351 Naturschaden. Erlittener Schaden kann den Effekt unterbrechen. Kann nur draußen verwendet werden." }
entries[26990] = { ["name"] = "Mal der Wildnis", ["text"] = "565 Mana 30 Meter Reichweite\nSofort\nErhöht 30 Min. lang die Rüstung des befreundeten Ziels um 340, alle Attribute um 14 und alle Widerstandsarten um 25." }
entries[26991] = { ["name"] = "Gabe der Wildnis", ["text"] = "1515 Mana 40 Meter Reichweite\nSofort\nReagenzien:\nWilde Federranke\nErhöht 1 Stunde lang die Rüstung der Gruppenmitglieder um 340, alle Attribute um 14 und alle Widerstandsarten um 25." }
entries[26992] = { ["name"] = "Dornen", ["text"] = "400 Mana 30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem, der es schlägt, 25 Naturschaden zufügen. Hält 10 Min. lang an." }
entries[26993] = { ["name"] = "Feenfeuer", ["text"] = "145 Mana 30 Meter Reichweite\nSofort\nVerringert die Rüstung des Ziels 40 Sek. lang um 610. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
entries[26994] = { ["name"] = "Wiedergeburt", ["text"] = "68% von Grundmana 30 Meter Reichweite\nWirken in 2 sek. 20 min Abklingzeit\nReagenzien:\nFlintgrassaat\nLässt den Geist in den Körper zurückkehren und bringt ein totes Ziel mit 3200 Gesundheit und 3200 Mana wieder ins Leben zurück." }
entries[26995] = { ["name"] = "Tier besänftigen", ["text"] = "140 Mana 40 Meter Reichweite\nWirken in 1.5 sek." }
entries[26996] = { ["name"] = "Zermalmen", ["text"] = "15 Wut Nahkampfreichweite\nNächster Nahkampf\nBenötigt Bärengestalt, Terrorbärengestalt\nErhöht den nächsten Angriffsschaden des Druiden um 176." }
entries[26997] = { ["name"] = "Prankenhieb", ["text"] = "20 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nSchlägt 3 in der Nähe befindliche Feinde und verursacht 84 Schaden, erhöht durch Angriffskraft." }
entries[26998] = { ["name"] = "Demoralisierendes Gebrüll", ["text"] = "10 Wut\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nDer Druide brüllt und verringert damit die Nahkampfangriffskraft von in der Nähe befindlichen Feinden um 248. Hält 30 Sek. lang an." }
entries[26999] = { ["name"] = "Rasende Regeneration", ["text"] = "Sofort 3 min Abklingzeit\nBenötigt Bärengestalt, Terrorbärengestalt\nWandelt 10 Sek. lang bis zu 10 Wutpunkte pro Sekunde in Gesundheit um. Jeder Wutpunkt wird in 25 Gesundheit umgewandelt." }
entries[27000] = { ["name"] = "Klaue", ["text"] = "45 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nDen Feind mit Klauen beharken und ihm so zusätzlich 190 Schaden zufügen. Gewährt 1 Combopunkt.\n(Procchance: 40%)" }
entries[27001] = { ["name"] = "Schreddern", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nSchreddert das Ziel, wobei dem Ziel 225% Schaden plus 236 zugefügt wird. Muss hinter dem Ziel sein. Gewährt 1 Combopunkt." }
entries[27002] = { ["name"] = "Schreddern", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nSchreddert das Ziel, wobei dem Ziel 225% Schaden plus 405 zugefügt wird. Muss hinter dem Ziel sein. Gewährt 1 Combopunkt." }
entries[27003] = { ["name"] = "Krallenhieb", ["text"] = "40 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nAttackiert das Ziel mit Krallen, fügt (Angriffskraft / 100 + 78) Blutungsschaden sowie 9 Sek. lang insgesamt (36 * 3 + Angriffskraft * 0.06) zusätzlichen Schaden zu. Gewährt 1 Combopunkt." }
entries[27004] = { ["name"] = "Ducken", ["text"] = "20 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Katzengestalt\nDucken verursacht zwar keinen Schaden, verringert aber Eure Bedrohung und senkt die Wahrscheinlichkeit, dass der Feind Euch angreift." }
entries[27005] = { ["name"] = "Verheeren", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nVerheert das Ziel, wobei dem Ziel 385% Schaden plus 514 zugefügt wird. Muss schleichen und hinter dem Ziel sein. Gewährt 1 Combopunkt." }
entries[27006] = { ["name"] = "Anspringen", ["text"] = "50 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nAnspringen betäubt das Ziel 3 Sek. lang und verursacht 18 Sek. lang insgesamt 600 Schaden. Erfordert, dass der Druide schleicht. Gewährt 1 Combopunkt." }
entries[27007] = { ["name"] = "Anspringblutung" }
entries[27008] = { ["name"] = "Zerfetzen", ["text"] = "30 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden im Lauf der Zeit verursacht. Der Schaden erhöht sich pro Combopunkt sowie durch Eure Angriffskraft:\n1 Punkt: 12 Sek. lang 300 Schaden.\n2 Punkte: 12 Sek. lang 498 Schaden.\n3 Punkte: 12 Sek. lang 696 Schaden.\n4 Punkte: 12 Sek. lang 894 Schaden.\n5 Punkte: 12 Sek. lang 1092 Schaden." }
entries[27009] = { ["name"] = "Griff der Natur", ["text"] = "Sofort 1 min Abklingzeit\n(Procchance: 35%)" }
entries[27010] = { ["name"] = "Wucherwurzeln", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nLässt das Ziel an Ort und Stelle festwurzeln und verursacht 27 Sek. lang insgesamt 351 Naturschaden. Erlittener Schaden kann den Effekt unterbrechen. Kann nur draußen verwendet werden." }
entries[27011] = { ["name"] = "Feenfeuer (Tiergestalt)", ["text"] = "30 Meter Reichweite\nSofort 6 sek. Abklingzeit\nBenötigt Katzengestalt, Bärengestalt, Terrorbärengestalt\nVerringert die Rüstung des Ziels 40 Sek. lang um 610. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
entries[27012] = { ["name"] = "Hurrikan", ["text"] = "1905 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.) 1 min Abklingzeit\nErzeugt einen wütenden Sturm im Zielgebiet, der Feinden alle 1 Sek. 206 Naturschaden zufügt und die Zeit zwischen Angriffen um 25% verringert. Hält 10 Sek. lang an. Ein Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten." }
entries[27013] = { ["name"] = "Insektenschwarm", ["text"] = "175 Mana 30 Meter Reichweite\nSofort\nDas feindliche Ziel wird von Insekten umschwärmt, die dessen Trefferchance um 2% verringern und beim Betroffenen über 12 Sek. 792 Naturschaden verursachen." }
entries[27014] = { ["name"] = "Raptorstoß", ["text"] = "120 Mana Nahkampfreichweite\nNächster Nahkampf 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin heftiger Angriff, der den Nahkampfschaden um 170 erhöht." }
entries[27015] = { ["name"] = "Rückzug", ["text"] = "205 Mana Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe" }
entries[27016] = { ["name"] = "Schlangenbiss", ["text"] = "275 Mana 35 Meter Reichweite\nBenötigt Distanzwaffe\nBeißt das Ziel und verursacht 15 Sek. lang (Fernkampfangriffskraft * 0.1 + 132 * 5) Naturschaden. Es kann immer nur ein Biss oder Stich pro Jäger auf einem einzelnen Ziel aktiv sein." }
entries[27018] = { ["name"] = "Vipernbiss", ["text"] = "270 Mana 35 Meter Reichweite\n15 sek. Abklingzeit\nBenötigt Distanzwaffe\nBeißt das Ziel und zieht 8 Sek. lang 1368 Mana ab. Es kann immer nur jeweils ein Biss oder Stich pro Jäger auf einem beliebigen Ziel aktiv sein." }
entries[27019] = { ["name"] = "Arkaner Schuss", ["text"] = "230 Mana 35 Meter Reichweite\n6 sek. Abklingzeit\nBenötigt Distanzwaffe\nEin sofortiger Schuss, der (Fernkampfangriffskraft * 0.15 + 273) Arkanschaden verursacht und 1 magischen Effekt bannt." }
entries[27020] = { ["name"] = "Ablenkender Schuss", ["text"] = "140 Mana 35 Meter Reichweite\n8 sek. Abklingzeit\nBenötigt Distanzwaffe" }
entries[27021] = { ["name"] = "Mehrfachschuss", ["text"] = "275 Mana 35 Meter Reichweite\nSofort 10 sek. Abklingzeit\nBenötigt Distanzwaffe\nFeuert mehrere Geschosse ab, trifft 3 Ziele und fügt zusätzliche 205 Schaden zu." }
entries[27022] = { ["name"] = "Salve", ["text"] = "585 Mana 35 Meter Reichweite\n1 min Abklingzeit\nBenötigt Distanzwaffe\nFeuert kontinuierlich eine Salve Munition auf das Zielgebiet und verursacht 6 Sek. lang pro Sekunde 105 Arkanschaden bei feindlichen Zielen im Umkreis von 8 Metern." }
entries[27023] = { ["name"] = "Feuerbrandfalle", ["text"] = "305 Mana\nSofort 30 sek. Abklingzeit\nEine Feuerfalle platzieren, die dem ersten sich nähernden Feind 15 Sek. lang insgesamt (Fernkampfangriffskraft * 0.1 + 197 * 5) Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[27024] = { ["name"] = "Feuerbrandfalle" }
entries[27025] = { ["name"] = "Sprengfalle", ["text"] = "650 Mana\nSofort 30 sek. Abklingzeit\nEine Feuerfalle platzieren, die explodiert, wenn sich ein Feind nähert. Die Falle verursacht (Fernkampfangriffskraft * 0.1 + 263) bis (Fernkampfangriffskraft * 0.1 + 337) Feuerschaden und verbrennt alle Feinde in einem Umkreis von 10 Metern, indem sie ihnen 20 Sek. lang insgesamt 450 zusätzlichen Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
