entries[27038] = { ["name"] = "Gesundheit des Begleiters +3% erhöht", ["text"] = "Erhöht die maximale Gesundheit Eures Begleiters um 3%." }
entries[27039] = { ["name"] = "Gesundheit des Begleiters +3% erhöht", ["text"] = "100 Meter Reichweite\nSofort\nErhöht die maximale Gesundheit Eures Begleiters um [Quellwert]%.", ["unresolvedValues"] = true }
entries[27042] = { ["name"] = "Kritische Trefferschance des Begleiters +2% erhöht", ["text"] = "100 Meter Reichweite\nSofort\nErhöht die Chance Eures Begleiters für einen kritischen Treffer um 2%." }
entries[27043] = { ["name"] = "Kritische Trefferschance des Begleiters +2% erhöht", ["text"] = "Erhöht die Chance Eures Begleiters für einen kritischen Treffer um 2%." }
entries[27044] = { ["name"] = "Aspekt des Falken", ["text"] = "140 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 155 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[27045] = { ["name"] = "Aspekt der Wildnis", ["text"] = "150 Mana\nSofort\nDer Jäger und alle Gruppenmitglieder in einem Umkreis von 30 Metern nehmen die Aspekte der Wildnis an: Der Naturwiderstand wird um 70 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[27046] = { ["name"] = "Tier heilen", ["text"] = "300 Mana 45 Meter Reichweite\nSofort\nHeilt Euer Tier 15 Sek. lang für 2375 Gesundheit." }
entries[27047] = { ["name"] = "Knurren", ["text"] = "15 Fokus Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nVerspottet das Ziel und erhöht damit die Chance, dass die Kreatur ihre Angriffe auf Euch fokussiert." }
entries[27048] = { ["name"] = "Ducken", ["text"] = "15 Fokus Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nDucken verursacht zwar keinen Schaden, verringert aber Eure Bedrohung und senkt die Wahrscheinlichkeit, dass der Feind Euch angreift." }
entries[27049] = { ["name"] = "Klaue", ["text"] = "25 Fokus Nahkampfreichweite\nSpontanzauber\nDen Feind mit Klauen beharken und ihm 54 bis 76 Schaden zufügen." }
entries[27050] = { ["name"] = "Beißen", ["text"] = "35 Fokus Nahkampfreichweite\nSpontanzauber 10 sek. Abklingzeit\nDen Feind beißen und ihm 108 bis 132 Schaden zufügen." }
entries[27051] = { ["name"] = "Schrei", ["text"] = "20 Fokus Nahkampfreichweite\nSpontanzauber\nEin Ziel erleidet 33 bis 61 Schaden, zusätzlich erfahren alle feindlichen Ziele in Nahkampfreichweite eine Reduzierung ihrer Nahkampfsangriffskraft um 210. Dieser Effekt hält 4 Sek. lang an." }
entries[27052] = { ["name"] = "Arkanwiderstand", ["text"] = "Erhöht den Arkanwiderstand um 140." }
entries[27053] = { ["name"] = "Feuerwiderstand", ["text"] = "Erhöht den Feuerwiderstand um 140." }
entries[27054] = { ["name"] = "Frostwiderstand", ["text"] = "Erhöht den Frostwiderstand um 140." }
entries[27055] = { ["name"] = "Naturwiderstand", ["text"] = "Erhöht den Naturwiderstand um 140." }
entries[27056] = { ["name"] = "Schattenwiderstand", ["text"] = "Erhöht den Schattenwiderstand um 140." }
entries[27057] = { ["name"] = "Schwarzer Diamant", ["text"] = "Wirken in 3 sek.\nReagenzien:\nMakelloser schwarzer Diamant (2)" }
entries[27060] = { ["name"] = "Skorpidgift", ["text"] = "30 Fokus Nahkampfreichweite\nSpontanzauber 4 sek. Abklingzeit\nFügt 10 Sek. lang 55 Naturschaden zu. Effekt ist auf einem einzelnen Ziel bis zu 5-mal stapelbar." }
entries[27061] = { ["name"] = "Natürliche Rüstung", ["text"] = "Rüstung um 1600 erhöht." }
entries[27062] = { ["name"] = "Große Ausdauer", ["text"] = "Ausdauer um 64 erhöht." }
entries[27063] = { ["name"] = "Donnerstampfer", ["text"] = "60 FokusSpontanzauber 1 min Abklingzeit\nLässt den Boden mit donnernder Macht erbeben und verursacht bei allen Feinden in einem Umkreis von 8 Metern 161 bis 185 Naturschaden. Diese Fähigkeit verursacht zusätzliche Bedrohung." }
entries[27065] = { ["name"] = "Gezielter Schuss", ["text"] = "370 Mana 35 Meter Reichweite\nWirken in 2.5 sek. 6 sek. Abklingzeit\nBenötigt Distanzwaffe\nEin gezielter Schuss, der den Distanzschaden um 870 erhöht und auf das Ziel gewirkte Heileffekte um 50% verringert. Hält 10 Sek. lang an." }
entries[27066] = { ["name"] = "Aura des Volltreffers", ["text"] = "Sofort\nErhöht die Angriffskraft von Gruppenmitgliedern in einem Umkreis von 45 Metern um 125. Hält bis Abbruch an." }
entries[27067] = { ["name"] = "Gegenangriff", ["text"] = "110 Mana Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nEin Schlag, der aktiv wird, nachdem ein gegnerischer Angriff pariert wurde. Dieser Angriff fügt 165 Schaden zu und macht das Ziel 5 Sek. lang bewegungsunfähig. Auf 'Gegenangriff' kann nicht mit 'Blocken', 'Ausweichen' oder 'Parieren' reagiert werden." }
entries[27068] = { ["name"] = "Stich des Flügeldrachen", ["text"] = "255 Mana 35 Meter Reichweite\n2 min Abklingzeit\nBenötigt Distanzwaffe\nVerschießt einen Stachel, der das Ziel 12 Sek. lang einschläfert. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Wenn das Ziel wieder aufwacht, verursacht der Stich 12 Sek. lang insgesamt 942 Naturschaden. Auf dem Ziel kann gleichzeitig nur ein Biss oder Stich pro Jäger aktiv sein." }
entries[27069] = { ["name"] = "Stich des Flügeldrachen" }
entries[27070] = { ["name"] = "Feuerball", ["text"] = "425 Mana 35 Meter Reichweite\nWirken in 3.5 sek.\nSchleudert eine glühende Kugel hinaus, die 649 bis 821 Feuerschaden sowie 8 Sek. lang 84 zusätzlichen Feuerschaden verursacht." }
entries[27071] = { ["name"] = "Frostblitz", ["text"] = "300 Mana 30 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Frostblitz auf den Feind, der 548 bis 591 Frostschaden verursacht und 9 Sek. lang das Bewegungstempo um 40% reduziert." }
entries[27072] = { ["name"] = "Frostblitz", ["text"] = "330 Mana 30 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Frostblitz auf den Feind, der 600 bis 647 Frostschaden verursacht und 9 Sek. lang das Bewegungstempo um 40% reduziert." }
entries[27073] = { ["name"] = "Versengen", ["text"] = "165 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nVersengt den Feind und fügt ihm 278 bis 327 Feuerschaden zu." }
entries[27074] = { ["name"] = "Versengen", ["text"] = "180 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nVersengt den Feind und fügt ihm 305 bis 361 Feuerschaden zu." }
entries[27075] = { ["name"] = "Arkane Geschosse", ["text"] = "685 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nSchleudert arkane Geschosse auf den Feind und verursacht 5 Sek. lang alle 1 Sek. 245 Arkanschaden." }
entries[27076] = { ["name"] = "Arkane Geschosse", ["text"] = "30 Meter Reichweite\nSofort\nSchleudert ein arkanes Geschoss auf den Feind und verursacht 245 Arkanschaden." }
entries[27078] = { ["name"] = "Feuerschlag", ["text"] = "400 Mana 20 Meter Reichweite\nSofort 8 sek. Abklingzeit\nÜberzieht den Feind mit 555 bis 654 Feuerschaden." }
entries[27079] = { ["name"] = "Feuerschlag", ["text"] = "465 Mana 20 Meter Reichweite\nSofort 8 sek. Abklingzeit\nÜberzieht den Feind mit 664 bis 786 Feuerschaden." }
entries[27080] = { ["name"] = "Arkane Explosion", ["text"] = "465 Mana\nSofort\nVerursacht eine Explosion arkaner Magie um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern 313 bis 338 Arkanschaden zu." }
entries[27082] = { ["name"] = "Arkane Explosion", ["text"] = "545 Mana\nSofort\nVerursacht eine Explosion arkaner Magie um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern 377 bis 407 Arkanschaden zu." }
entries[27085] = { ["name"] = "Blizzard", ["text"] = "1645 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 8 sek.)\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 Sek. lang insgesamt ( 185 * 8) Frostschaden." }
entries[27086] = { ["name"] = "Flammenstoß", ["text"] = "1175 Mana 30 Meter Reichweite\nWirken in 3 sek.\nLässt eine Feuersäule niedergehen, die alle Feinde im Gebiet verbrennt und ihnen zunächst 480 bis 585 Feuerschaden und zusätzlich 8 Sek. lang 424 Feuerschaden zufügt." }
entries[27087] = { ["name"] = "Kältekegel", ["text"] = "645 Mana\nSofort 10 sek. Abklingzeit\nZiele in einem kegelförmigen Bereich vor dem Zaubernden erleiden 418 bis 457 Frostschaden und ihr Bewegungstempo wird 8 Sek. lang um 50% verlangsamt." }
entries[27088] = { ["name"] = "Frostnova", ["text"] = "185 Mana\nSofort 25 sek. Abklingzeit\nFügt in der Nähe des Zaubernden befindlichen Feinden 100 bis 113 Frostschaden zu und friert sie bis zu 8 Sek. lang ein. Erlittener Schaden kann den Effekt unterbrechen." }
entries[27089] = { ["name"] = "Trinken", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. insgesamt 7200 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[27090] = { ["name"] = "Wasser herbeizaubern", ["text"] = "885 Mana\nWirken in 3 sek.\nZaubert 10 Schläuche Eiswasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[27094] = { ["name"] = "Essen", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 30 Sek. 4320 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[27095] = { ["name"] = "Intuition", ["text"] = "Erhöht den Durch Eure Fähigkeiten 'Hinterhalt' und 'Erdrosseln' zufgefügten Schaden um 2% und gibt Euch eine Chance von 40%, zu bemerken, wenn Spieler Eure Verstohlenheit durchschauen." }
entries[27096] = { ["name"] = "Intuition", ["text"] = "Erhöht den Durch Eure Fähigkeiten 'Hinterhalt' und 'Erdrosseln' zufgefügten Schaden um 3% und gibt Euch eine Chance von 60%, zu bemerken, wenn Spieler Eure Verstohlenheit durchschauen." }
entries[27097] = { ["name"] = "Intuition", ["text"] = "Erhöht den Durch Eure Fähigkeiten 'Hinterhalt' und 'Erdrosseln' zufgefügten Schaden um 4% und gibt Euch eine Chance von 80%, zu bemerken, wenn Spieler Eure Verstohlenheit durchschauen." }
entries[27099] = { ["name"] = "Intuition", ["text"] = "Erhöht den Durch Eure Fähigkeiten 'Hinterhalt' und 'Erdrosseln' zufgefügten Schaden um 5% und gibt Euch eine Chance von 100%, zu bemerken, wenn Spieler Eure Verstohlenheit durchschauen." }
entries[27101] = { ["name"] = "Manasmaragd herbeizaubern", ["text"] = "1670 Mana\nWirken in 3 sek.\nZaubert einen Manasmaragd herbei, der zum sofortigen Wiederherstellen von 2340 bis 2460 Mana verwendet werden kann. 3 Aufladungen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[27103] = { ["name"] = "Mana auffüllen", ["text"] = "Sofort 1 min Abklingzeit\nStellt 2340 bis 2460 Mana wieder her." }
entries[27124] = { ["name"] = "Eisrüstung", ["text"] = "630 Mana\nSofort\nErhöht die Rüstung um 645 und den Frostwiderstand um 18. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an." }
entries[27125] = { ["name"] = "Magische Rüstung", ["text"] = "575 Mana\nSofort\nErhöht den Widerstand gegen alle Arten von Magie um 18 und gewährt dem Zaubernden jederzeit 30% seiner Manaregeneration. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an." }
entries[27126] = { ["name"] = "Arkane Intelligenz", ["text"] = "700 Mana 30 Meter Reichweite\nSofort\nErhöht 30 Min. lang die Intelligenz des Ziels um 40." }
entries[27127] = { ["name"] = "Arkane Brillanz", ["text"] = "1800 Mana 40 Meter Reichweite\nSofort\nReagenzien:\nArkanes Pulver\nErfüllt die Gruppe des Ziels mit Brillanz und erhöht Ihre Intelligenz 1 Stunde lang um 40." }
entries[27128] = { ["name"] = "Feuerzauberschutz", ["text"] = "360 Mana\nSofort 30 sek. Abklingzeit\nAbsorbiert 1125 Feuerschaden. Hält 30 Sek. lang an." }
entries[27130] = { ["name"] = "Magie verstärken", ["text"] = "500 Mana 30 Meter Reichweite\nSofort\nVerstärkt gegen das anvisierte Gruppenmitglied gerichtete Magie, wobei der von Zaubern zugefügte Schaden um bis zu 90 und Heilzauber um bis zu 180 erhöht werden. Hält 10 Min. lang an." }
entries[27131] = { ["name"] = "Manaschild", ["text"] = "155 Mana\nSofort\nAbsorbiert 715 Schaden und entzieht stattdessen Mana. Entzieht pro absorbiertem Schaden 2 Mana. Hält 1 Min. lang an." }
entries[27132] = { ["name"] = "Pyroschlag", ["text"] = "460 Mana 35 Meter Reichweite\nWirken in 6 sek.\nSchleudert einen riesigen feurigen Felsen hinaus, der 866 bis 1094 Feuerschaden sowie zusätzlich 12 Sek. lang insgesamt 312 Feuerschaden verursacht." }
entries[27133] = { ["name"] = "Druckwelle", ["text"] = "555 Mana\nSofort 30 sek. Abklingzeit\nEine Flammenwelle geht vom Zaubernden aus, fügt allen Feinden, die in diese hineingeraten, 543 bis 638 Feuerschaden zu und macht sie 6 Sek. lang benommen." }
entries[27134] = { ["name"] = "Eisbarriere", ["text"] = "495 Mana\nSofort 30 sek. Abklingzeit\nSchirmt Euch sofort ab und absorbiert 952 Schaden. Hält 1 Min. lang an. Solange der Schild hält, werden Zauber nicht unterbrochen." }
entries[27135] = { ["name"] = "Heiliges Licht", ["text"] = "710 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 1773 bis 1971." }
entries[27136] = { ["name"] = "Heiliges Licht", ["text"] = "840 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 2196 bis 2446." }
entries[27137] = { ["name"] = "Lichtblitz", ["text"] = "180 Mana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt ein befreundetes Ziel um 458 bis 513." }
entries[27138] = { ["name"] = "Exorzismus", ["text"] = "340 Mana 30 Meter Reichweite\nSofort 15 sek. Abklingzeit\nVerursacht 626 bis 698 Heiligschaden an einem untoten oder dämonischen Ziel." }
entries[27139] = { ["name"] = "Heiliger Zorn", ["text"] = "825 ManaWirken in 2 sek. 1 min Abklingzeit\nVerschleudert Blitze heiliger Macht in alle Richtungen und verursacht dabei 637 bis 748 Heiligschaden bei allen Untoten und Dämonen im Umkreis von 20 Metern." }
entries[27140] = { ["name"] = "Segen der Macht", ["text"] = "145 Mana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen und erhöht 10 Min. lang die Angriffskraft um 220. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27141] = { ["name"] = "Großer Segen der Macht", ["text"] = "295 Mana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen der Macht. Der große Segen der Macht erhöht die Angriffskraft 30 Min. lang um 220. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27142] = { ["name"] = "Segen der Weisheit", ["text"] = "150 Mana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen und stellt 10 Min. lang alle 5 Sek. 41 Mana wieder her. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27143] = { ["name"] = "Großer Segen der Weisheit", ["text"] = "310 Mana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen der Weisheit. Der große Segen der Weisheit stellt 30 Min. lang alle 5 Sek. 41 Mana wieder her. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27144] = { ["name"] = "Segen des Lichts", ["text"] = "180 Mana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen und verstärkt die Effekte von den Zaubern 'Heiliges Licht', die auf dieses Ziel angewandt werden, um bis zu 580 sowie die Effekte der Zauber 'Lichtblitz', die auf das Ziel angewandt werden, um bis zu 185. Hält 10 Min. lang an. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27145] = { ["name"] = "Großer Segen des Lichts", ["text"] = "360 Mana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen des Lichts. Der große Segen des Lichts erhöht die Effekte der auf das Ziel gewirkten Zauber 'Heiliges Licht' um 580 und 'Lichtblitz' um 185. Hält 30 Min. lang an. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27146] = { ["name"] = "Linkes Stück von Lord Valthalaks Amulett", ["text"] = "Wirken in 2 sek.\nReagenzien:\nObere Stück von Lord Valthalaks Amulett , Rechtes Stück von Lord Valthalaks Amulett\nFügt das linke, rechte und obere Stück von Lord Valthalaks Amulett wieder zu einem Ganzen zusammen." }
entries[27147] = { ["name"] = "Segen der Opferung", ["text"] = "115 Mana 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nWendet einen Segen auf das Gruppenmitglied an und überträgt 81 des erlittenen Schadens pro Treffer auf den Zaubernden. Hält 30 Sek. lang an. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27148] = { ["name"] = "Segen der Opferung", ["text"] = "135 Mana 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nWendet einen Segen auf das Gruppenmitglied an und überträgt 104 des erlittenen Schadens pro Treffer auf den Zaubernden. Hält 30 Sek. lang an. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27149] = { ["name"] = "Aura der Hingabe", ["text"] = "Sofort\nGibt Gruppenmitgliedern in einem Umkreis von 30 Metern 861 zusätzliche Rüstung. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[27150] = { ["name"] = "Aura der Vergeltung", ["text"] = "Sofort\nVerursacht 26 Heiligschaden für jede Kreatur, die ein Gruppenmitglied schlägt, das sich im Umkreis von 30 Metern befindet. Die Spieler können pro Paladin nur jeweils eine Aura besitzen." }
entries[27151] = { ["name"] = "Aura des Schattenwiderstands", ["text"] = "Sofort\nErhöht den Schattenwiderstand aller sich im Umkreis von 30 Metern befindlichen Gruppenmitglieder um 70. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[27152] = { ["name"] = "Aura des Frostwiderstands", ["text"] = "Sofort\nErhöht den Frostwiderstand aller sich im Umkreis von 30 Metern befindlichen Gruppenmitglieder um 70. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[27153] = { ["name"] = "Aura des Feuerwiderstands", ["text"] = "Sofort\nErhöht den Feuerwiderstand aller sich im Umkreis von 30 Metern befindlichen Gruppenmitglieder um 70. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[27154] = { ["name"] = "Handauflegung", ["text"] = "40 Meter Reichweite\nSofort 1 Stunde Abklingzeit\nHeilt ein befreundetes Ziel um einen Betrag, der der maximalen Gesundheit des Paladins entspricht, und stellt 900 seines Manas wieder her. Entzieht dem Paladin bei Verwendung sämtliches noch vorhandenes Mana." }
entries[27155] = { ["name"] = "Siegel der Rechtschaffenheit", ["text"] = "260 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit heiligem Geist, der jedem Nahkampfangriff zusätzlichen Heiligschaden in Höhe von [1.2 * ( 2324 * 1.2 * 1.03 * Haupthandwaffen-Max-Grundgeschwindigkeit / 100) + 0.03 * (Haupthandwaffen-Max-Schaden + Haupthandwaffen-Min-Schaden) / 2 + 1] verleiht. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Feind 225 bis 246 Heiligschaden zu." }
entries[27156] = { ["name"] = "Siegel der Rechtschaffenheit" }
entries[27157] = { ["name"] = "Richturteil der Rechtschaffenheit" }
entries[27158] = { ["name"] = "Siegel des Kreuzfahrers", ["text"] = "210 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit dem Geist eines Kreuzfahrers und verleiht 495 Nahkampfangriffskraft. Außerdem greift der Paladin um 40% schneller an, verursacht jedoch bei jedem Angriff weniger Schaden. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 20 Sek. lang und erhöht den erlittenen Heiligschaden um bis zu 219. Eure Nahkampfangriffe frischen die Dauer dieses Siegels auf. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[27159] = { ["name"] = "Richturteil des Kreuzfahrers" }
entries[27160] = { ["name"] = "Siegel des Lichts", ["text"] = "280 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit göttlichem Licht, das jedem Nahkampfangriff eine Chance verleiht, den Paladin um 133 zu heilen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 20 Sek. lang und verleiht Nahkampfangriffen, die gegen den gerichteten Feind ausgeführt werden, eine Chance den Angreifer um 95 zu heilen. Eure Nahkampfangriffe erneuern die Dauer dieses Effekts. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[27161] = { ["name"] = "Siegel des Lichts" }
entries[27162] = { ["name"] = "Richturteil des Lichts", ["text"] = "100 Meter Reichweite\nSofort\n(Procchance: 50%)" }
entries[27163] = { ["name"] = "Richturteil des Lichts" }
entries[27164] = { ["name"] = "Richturteil der Weisheit", ["text"] = "100 Meter Reichweite\nSofort\n(Procchance: 50%)" }
entries[27165] = { ["name"] = "Richturteil der Weisheit" }
entries[27166] = { ["name"] = "Siegel der Weisheit", ["text"] = "270 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit göttlicher Weisheit, die jedem Nahkampfangriff eine Chance verleiht, 121 Mana des Paladins wiederherzustellen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 20 Sek. lang und verleiht Angriffen und Zaubern, die gegen den gerichteten Feind ausgeführt werden, eine Chance beim Angreifer 74 Mana wiederherzustellen. Eure Nahkampfangriffe erneuern die Dauer dieses Effekts. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[27167] = { ["name"] = "Siegel der Weisheit" }
entries[27168] = { ["name"] = "Segen des Refugiums", ["text"] = "180 Mana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen und verringert dabei jeglichen zugefügten Schaden von allen Quellen 10 Min. lang um bis zu 80. Zusätzlich nimmt ein Angreifer 46 Heiligschaden, wenn das Ziel einen Nahkampfangriff blockt. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27169] = { ["name"] = "Großer Segen des Refugiums", ["text"] = "360 Mana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen des Refugiums. Der große Segen des Refugiums reduziert sämtlichen beim Ziel verursachten Schaden 30 Min. lang um 80. Zusätzlich verursacht ein Ziel, wenn es einen Angriff blockt, beim Angreifer 46 Heiligschaden. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27170] = { ["name"] = "Siegel des Befehls", ["text"] = "280 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit dem Geist des Befehls und gewährt ihm die Chance, zusätzlich zum erzielten Waffenschaden, Heiligschaden in Höhe von 70% des normalen Waffenschadens zuzufügen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind und verursacht sofortigen Heiligschaden in Höhe von 228 bis 252, oder 456 bis 504 Heiligschaden, sollte das Ziel betäubt oder handlungsunfähig sein.\n(1s Abklingzeit)" }
entries[27171] = { ["name"] = "Richturteil des Befehls" }
entries[27172] = { ["name"] = "Richturteil des Befehls" }
entries[27173] = { ["name"] = "Weihe", ["text"] = "660 Mana\nSofort 8 sek. Abklingzeit\nWeiht das Land unter dem Paladin, fügt 8 Sek. lang Feinden, die das Gebiet betreten, 512 Heiligschaden zu." }
entries[27174] = { ["name"] = "Heiliger Schock", ["text"] = "575 Mana 20 Meter Reichweite\nSofort 15 sek. Abklingzeit\nTrifft das Ziel mit heiliger Energie. Verursacht 614 bis 664 Heiligschaden bei Feinden oder heilt 777 bis 841 bei Verbündeten." }
entries[27175] = { ["name"] = "Heiliger Schock" }
entries[27176] = { ["name"] = "Heiliger Schock" }
entries[27177] = { ["name"] = "Entweiht" }
entries[27179] = { ["name"] = "Heiliger Schild", ["text"] = "280 Mana\nSofort 10 sek. Abklingzeit\nErhöht die Blockchance 10 Sek. lang um 30% und fügt, solange aktiv, für jeden geblockten Angriff 155 Heiligschaden zu. Der durch 'Heiliger Schild' verursachte Schaden erzeugt 35% zusätzliche Bedrohung. Jedes Blocken verbraucht eine der 4 Aufladungen." }
entries[27180] = { ["name"] = "Hammer des Zorns", ["text"] = "440 Mana 30 Meter Reichweite\nWirken in 0.5 sek. 6 sek. Abklingzeit\nSchleudert einen Hammer gegen einen Feind und fügt 672 bis 742 Heiligschaden zu. Nur auf Ziele anwendbar, die über 20% oder weniger Gesundheit verfügen." }
entries[27181] = { ["name"] = "Nethermantel", ["text"] = "24% von Grundmana\nWirken in 3 sek.\nDer Hexenmeister hüllt sich in Netherenergie und wird dadurch immun gegen den nächsten körperlichen Schaden verursachende Angriff. Zusätzlich werden 6 Sek. lang die Trefferchance des Angreifers um 25% und sein Widerstand gegen Furcht- und Schreckenseffekte um 10% verringert. Hält 10 Min. lang an." }
entries[27182] = { ["name"] = "Netherleiden" }
entries[27183] = { ["name"] = "Entweihen" }
entries[27184] = { ["name"] = "Summon Mor Grayhoof DND", ["text"] = "10 Meter Reichweite\nSofort\nBeschwört den Geist von Mor Grauhuf." }
entries[27186] = { ["name"] = "Tödliches Gift VII", ["text"] = "Wirken in 3 sek.\nBenötigt Nahkampfwaffe\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 Sek. lang für 180 Naturschaden zu vergiften. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden.\n(Procchance: 30%)" }
entries[27187] = { ["name"] = "Tödliches Gift VII" }
entries[27188] = { ["name"] = "Wundgift", ["text"] = "Wirken in 3 sek.\nBenötigt Nahkampfwaffe\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, wodurch dieser 65 Naturschaden erleidet und alle auf ihn gewirkten Heileffekte 15 Sek. lang um 10% verringert werden. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden.\n(Procchance: 30%)" }
entries[27189] = { ["name"] = "Wundgift" }
entries[27190] = { ["name"] = "Summon Isalien DND", ["text"] = "40 Meter Reichweite\nSofort\nBeschwört den Geist von Isalien." }
entries[27191] = { ["name"] = "Summon Jarien and Sothos DND", ["text"] = "40 Meter Reichweite\nSofort\nBeschwört die Überreste von Jarien und Sothos." }
entries[27192] = { ["name"] = "Entweihen" }
entries[27193] = { ["name"] = "Entweihen" }
