entries[27201] = { ["name"] = "Summon Kormok DND", ["text"] = "40 Meter Reichweite\nSofort\nBeschwört den Geist von Kormok." }
entries[27202] = { ["name"] = "Summon Lord Valthalak DND", ["text"] = "40 Meter Reichweite\nSofort\nBeschwört den Geist von Lord Valthalak." }
entries[27203] = { ["name"] = "Summon Various DND", ["text"] = "40 Meter Reichweite\nSofort\nBeschwört an verfluchten Orten die Geister der Toten." }
entries[27205] = { ["name"] = "Schaden des Begleiters +3% erhöht", ["text"] = "100 Meter Reichweite\nSofort\nErhöht den von Eurem Begleiter angerichteten Schaden um 3%." }
entries[27206] = { ["name"] = "Schaden des Begleiters +3% erhöht", ["text"] = "Erhöht den von Eurem Begleiter angerichteten Schaden um 3%." }
entries[27208] = { ["name"] = "Rüstung des Begleiters +10% erhöht", ["text"] = "100 Meter Reichweite\nSofort\nErhöht die Rüstung Eures Begleiters um [Quellwert]%.", ["unresolvedValues"] = true }
entries[27209] = { ["name"] = "Schattenblitz", ["text"] = "420 Mana 30 Meter Reichweite\nWirken in 3 sek.\nSendet einen schattigen Blitz zum Gegner, der 544 bis 607 Schattenschaden verursacht." }
entries[27210] = { ["name"] = "Sengender Schmerz", ["text"] = "191 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nFügt dem Ziel sengenden Schmerz zu und verursacht 252 bis 297 Feuerschaden. Verursacht ein hohes Maß an Bedrohung." }
entries[27211] = { ["name"] = "Seelenfeuer", ["text"] = "215 Mana 30 Meter Reichweite\nWirken in 6 sek. 1 min Abklingzeit\nReagenzien:\nSeelensplitter\nVerbrennt die Seele eines Feindes und verursacht 853 bis 1065 Feuerschaden." }
entries[27212] = { ["name"] = "Feuerregen", ["text"] = "1480 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 8 sek.)\nLässt einen feurigen Regen niedergehen, der 8 Sek. lang Feinde im Wirkungsbereich mit insgesamt ( 304 * 4) Feuerschaden verbrennt." }
entries[27213] = { ["name"] = "Höllenfeuer", ["text"] = "1665 Mana\nKanalisiert (Wirken in 15 sek.)\nEntzündet den Bereich um den Zaubernden herum, fügt ihm selbst alle 1 Sek. 308 Feuerschaden zu sowie im gleichen Rythmus allen in der Nähe befindlichen Feinden 308 Feuerschaden. Hält 15 Sek. lang an." }
entries[27214] = { ["name"] = "Höllenfeuer" }
entries[27215] = { ["name"] = "Feuerbrand", ["text"] = "445 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt den Feind und fügt 332 Feuerschaden sowie 15 Sek. lang 615 zusätzlichen Schaden zu." }
entries[27216] = { ["name"] = "Verderbnis", ["text"] = "370 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerdirbt das Ziel und verursacht 18 Sek. lang 900 Schattenschaden." }
entries[27217] = { ["name"] = "Seelendieb", ["text"] = "360 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 15 sek.)\nEntzieht dem Ziel die Seele und verursacht 15 Sek. lang 620 Schattenschaden. Wenn das Ziel beim Entziehen der Seele stirbt und Erfahrung oder Ehrenpunkte abgibt, erhält der Zaubernde einen Seelensplitter. Seelensplitter werden für andere Zauber benötigt." }
entries[27218] = { ["name"] = "Fluch der Pein", ["text"] = "265 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 Sek. lang 1356 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[27219] = { ["name"] = "Blutsauger", ["text"] = "355 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 87 Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
entries[27220] = { ["name"] = "Blutsauger", ["text"] = "425 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 108 Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
entries[27221] = { ["name"] = "Mana entziehen", ["text"] = "385 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 169 Mana vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
entries[27222] = { ["name"] = "Aderlass", ["text"] = "Sofort\nWandelt 582 Gesundheit in 582 Mana um." }
entries[27223] = { ["name"] = "Todesmantel", ["text"] = "600 Mana 30 Meter Reichweite\nSofort 2 min Abklingzeit\nVerursacht 526 Schattenschaden und das betroffene Ziel läuft 3 Sek. lang voller Entsetzen davon. Der Zaubernde erhält 100% des verursachten Schadens in Gesundheit." }
entries[27224] = { ["name"] = "Fluch der Schwäche", ["text"] = "215 Mana 30 Meter Reichweite\nSofort\nDie Nahkampfangriffskraft des Ziels wird 2 Min. lang um 257 reduziert. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[27225] = { ["name"] = "Rüstung des Begleiters +10% erhöht", ["text"] = "Erhöht die Rüstung Eures Begleiters um 10%." }
entries[27226] = { ["name"] = "Fluch der Tollkühnheit", ["text"] = "160 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Tollkühnheit, wodurch sich die Nahkampfangriffskraft 2 Min. lang um 135 erhöht, jedoch die Rüstung um 800 verringert. Mit einem Fluch belegte Feinde fliehen nicht und ignorieren Furcht- und Entsetzenseffekte. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[27228] = { ["name"] = "Fluch der Elemente", ["text"] = "260 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel und verringert 5 Min. lang seinen Arkan-, Feuer-, Frost- und Schattenwiderstand um 88. Erhöht außerdem den erlittenen Arkan-, Feuer-, Frost- und Schattenschaden des Ziels um 10%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[27229] = { ["name"] = "Fluch der Schatten", ["text"] = "260 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel und verringert 5 Min. lang seinen Schatten- und Arkanwiderstand um 88. Erhöht außerdem den erlittenen Schatten- und Arkanschaden um 10%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[27230] = { ["name"] = "Gesundheitsstein herstellen", ["text"] = "1390 Mana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nLässt einen meisterlichen Gesundheitsstein entstehen, der verwendet werden kann, um sofort 2080 Gesundheit wiederherzustellen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[27235] = { ["name"] = "Meisterlicher Gesundheitsstein", ["text"] = "Sofort\nStellt sofort 2080 Gesundheit wieder her." }
entries[27236] = { ["name"] = "Meisterlicher Gesundheitsstein", ["text"] = "Sofort\nStellt sofort 2288 Gesundheit wieder her." }
entries[27237] = { ["name"] = "Meisterlicher Gesundheitsstein", ["text"] = "Sofort\nStellt sofort 2496 Gesundheit wieder her." }
entries[27238] = { ["name"] = "Seelenstein herstellen", ["text"] = "68% von Grundmana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nLässt einen meisterlichen Seelenstein entstehen. Der Seelenstein kann zum Speichern der Seele eines Ziels benutzt werden. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 2900 Gesundheit und 3300 Mana wiederbelebt werden.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[27239] = { ["name"] = "Seelensteinauferstehung", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nSpeichert die Seele des befreundeten Ziels. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 2900 Gesundheit und 3300 Mana wiederbelebt werden." }
entries[27240] = { ["name"] = "Seelenstein" }
entries[27241] = { ["name"] = "Gurky beschwören", ["text"] = "Wirken in 1 sek.\nMit Rechtsklick Euren Gurky beschwören und freigeben." }
entries[27242] = { ["name"] = "Belohnung UND Questobjekt erhalten, Wache von Sturmwind" }
entries[27243] = { ["name"] = "Saat der Verderbnis", ["text"] = "882 Mana 30 Meter Reichweite\nWirken in 2 sek.\nPflanzt dem feindlichen Ziel einen Samen der Verderbnis ein, der 18 Sek. lang insgesamt 1044 Schattenschaden verursacht. Wenn das Ziel insgesamt 1044 Schaden nimmt oder stirbt, verursacht der Samen bei allen anderen Feinden im Umkreis von 15 Metern um das Ziel 1110 bis 1290 Schattenschaden. Auf jedem Ziel kann pro Hexenmeister nur ein Verderbniszauber aktiv sein." }
entries[27244] = { ["name"] = "Belohnung UND Questobjekt erhalten, Wache von Eisenschmiede" }
entries[27245] = { ["name"] = "Belohnung UND Questobjekt erhalten, Wache von Darnassus" }
entries[27246] = { ["name"] = "Belohnung UND Questobjekt erhalten, Wache von Unterstadt" }
entries[27247] = { ["name"] = "Belohnung UND Questobjekt erhalten, Wache von Orgrimmar" }
entries[27248] = { ["name"] = "Belohnung UND Questobjekt erhalten, Wache von Donnerfels" }
entries[27249] = { ["name"] = "Spektralen Assassinen beschwören" }
entries[27250] = { ["name"] = "Feuerstein herstellen", ["text"] = "1330 Mana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nStellt einen meisterlichen Feuerstein her, der angelegt werden kann. Wenn angelegt, wird die Waffenhandwaffe mit Feuer verzaubert und gewährt jedem Angriff die Chance, 116 bis 174 zusätzlichen Feuerschaden zuzufügen. Außerdem erhöht das Anlegen eines meisterlichen Feuersteins den Schaden von Feuerzaubern um 30.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[27252] = { ["name"] = "Feuerstein", ["text"] = "Verzaubert eine Waffe mit Feuer und gewährt jedem Angriff eine Chance, 116 bis 174 zusätzlichen Feuerschaden zuzufügen." }
entries[27253] = { ["name"] = "Meisterlicher Feuerstein", ["text"] = "100 Meter Reichweite\nSofort\nFeuerschaden." }
entries[27254] = { ["name"] = "Schaden8" }
entries[27255] = { ["name"] = "Schaden9" }
entries[27256] = { ["name"] = "Feuerschaden erhöhen 30", ["text"] = "Erhöht den von Feuerzaubern und -effekten zugefügten Schaden um bis zu 30." }
entries[27258] = { ["name"] = "Schaden10" }
entries[27259] = { ["name"] = "Lebenslinie", ["text"] = "99 Gesundheit und 65 pro Sek. 20 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nGibt dem Begleiter des Zaubernden 10 Sek. lang in jeder Sekunde 188 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert." }
entries[27260] = { ["name"] = "Dämonenrüstung", ["text"] = "820 Mana\nSofort\nSchützt den Zaubernden und erhöht die Rüstung um 660, den Schattenwiderstand um 18 und stellt alle 5 Sek. 18 Gesundheit wieder her. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Hexenmeister aktiv sein. Hält 30 Min. an." }
entries[27261] = { ["name"] = "Schaden11" }
entries[27263] = { ["name"] = "Schattenbrand", ["text"] = "435 Mana 20 Meter Reichweite\nSofort 15 sek. Abklingzeit\nReagenzien:\nSeelensplitter\nÜberzieht das Ziel sofort mit 538 bis 599 Schattenschaden. Wenn das Ziel innerhalb von 5 Sek. nach 'Schattenbrand' stirbt und Erfahrung oder Ehrenpunkte abgibt, erhält der Zaubernde einen Seelensplitter." }
entries[27264] = { ["name"] = "Lebensentzug", ["text"] = "350 Mana 30 Meter Reichweite\nSofort\nÜberträgt alle 3 Sek. 52 Gesundheit vom Ziel auf den Zaubernden. Hält 30 Sek. lang an." }
entries[27265] = { ["name"] = "Dunkler Pakt", ["text"] = "30 Meter Reichweite\nSofort\nZieht 700 vom Mana Eures Begleiters ab und gibt 100% an Euch zurück." }
entries[27266] = { ["name"] = "Feuersbrunst", ["text"] = "280 Mana 30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nEntzündet ein Ziel, das bereits mit Eurem 'Feuerbrand' infiziert ist, fügt 521 bis 648 Feuerschaden zu und verzehrt den Zauber 'Feuerbrand'." }
entries[27267] = { ["name"] = "Feuerblitz", ["text"] = "145 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerursacht 112 bis 127 Feuerschaden am Ziel." }
entries[27268] = { ["name"] = "Blutpakt", ["text"] = "20 Meter Reichweite\nSofort\nErhöht die Ausdauer der Gruppenmitglieder um 70." }
entries[27269] = { ["name"] = "Feuerschild", ["text"] = "210 Mana 30 Meter Reichweite\nSofort\nUmgibt das Ziel mit einem Schild aus Feuer. Der Feuerwiderstand des Zieles wird um 30 erhöht und jeder Schlag gegen das Ziel verursacht beim Angreifer 19 Feuerschaden. Hält 3 Min. lang an. Der Zaubernde kann 'Feuerschild' nicht auf sich selbst wirken." }
entries[27270] = { ["name"] = "Qual", ["text"] = "130 Mana Nahkampfreichweite\nSofort 5 sek. Abklingzeit" }
entries[27271] = { ["name"] = "Leiden", ["text"] = "305 Mana Nahkampfreichweite\nSofort 2 min Abklingzeit" }
entries[27272] = { ["name"] = "Schatten verzehren", ["text"] = "595 Mana\nKanalisiert (Wirken in 10 sek.)\nDer Leerwandler verzehrt in der Nähe befindliche Schatten, um seine Gestalt zu vergrößern, und stellt im Laufe von 10 Sek. 2415 Gesundheit wieder her. Zusätzlich erhöht sich die Angriffskraft des Leerwandlers 10 Min. lang um 200. Kann nicht während eines Kampfes verwendet werden." }
entries[27273] = { ["name"] = "Opferung", ["text"] = "Unbegrenzte Reichweite\nSofort\nOpfert den Leerwandler und gewährt seinem Besitzer einen Schild, der 30 Sek. lang 2900 Schaden absorbiert. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen." }
entries[27274] = { ["name"] = "Schmerzenspeitsche", ["text"] = "190 Mana Nahkampfreichweite\nSofort 12 sek. Abklingzeit\nEin sofortiger Angriff, der das Ziel peitscht und 123 Schattenschaden zufügt." }
entries[27275] = { ["name"] = "Besänftigender Kuss", ["text"] = "140 Mana 10 Meter Reichweite\nSofort 4 sek. Abklingzeit" }
entries[27276] = { ["name"] = "Magie verschlingen", ["text"] = "270 Mana 30 Meter Reichweite\nSofort 8 sek. Abklingzeit\nReinigt und entzieht 1 schädlichen Magieeffekt von einem Freund oder 1 nützlichen Magieeffekt von einem Feind. Wird ein Effekt verschlungen, wird der Teufelsjäger um 775 geheilt." }
entries[27277] = { ["name"] = "Magie verschlingen", ["text"] = "330 Mana 30 Meter Reichweite\nSofort 8 sek. Abklingzeit\nReinigt und entzieht 1 schädlichen Magieeffekt von einem Freund oder 1 nützlichen Magieeffekt von einem Feind. Wird ein Effekt verschlungen, wird der Teufelsjäger um 915 geheilt." }
entries[27278] = { ["name"] = "Magie verschlingen" }
entries[27279] = { ["name"] = "Magie verschlingen" }
entries[27280] = { ["name"] = "Besudeltes Blut", ["text"] = "215 Mana\nSofort\nBesudelt 1 Min. lang das Teufelsjägerblut. Wenn der Teufelsjäger mit einem Nahkampfangriff getroffen wird, verliert der Angreifer 10 Sek. lang 95 Angriffskraft. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden." }
entries[27281] = { ["name"] = "Besudeltes Blut" }
entries[27282] = { ["name"] = "Tödliches Gift VII", ["text"] = "Wirken in 3 sek.\nReagenzien:\nJungfernleid , Kristallphiole\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 Sek. lang für 180 Naturschaden zu vergiften. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden." }
entries[27283] = { ["name"] = "Wundgift V", ["text"] = "Wirken in 3 sek.\nReagenzien:\nEssenz der Pein (2), Kristallphiole\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, 65 Naturschaden zu verursachen und alle auf den Gegner gewirkten Heileffekte 15 Sek. lang um 10% zu verringern. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden." }
entries[27285] = { ["name"] = "Saat der Verderbnis" }
entries[27286] = { ["name"] = "Schattenwut", ["text"] = "100 Mana" }
entries[27287] = { ["name"] = "Energieentzug" }
entries[27288] = { ["name"] = "Energieentzug" }
entries[27289] = { ["name"] = "Energieentzug" }
entries[27290] = { ["name"] = "Ruf erhöhen", ["text"] = "Wirken in 1 sek.\nErhöht dauerhaft Euren Ruf bei der Argentumdämmerung." }
entries[27291] = { ["name"] = "Magiestab beschwören" }
entries[27338] = { ["name"] = "Schattenstab" }
entries[27344] = { ["name"] = "Knurren", ["text"] = "100 Meter Reichweite\nSofort\nVerspottet das Ziel und erhöht damit die Chance, dass die Kreatur ihre Angriffe auf Euch fokussiert." }
